sql.where:
DELETED = 0

    AND ENTERPRISE_ID = #{enterpriseId}


    AND ENTERPRISE_NAME LIKE CONCAT('%', #{enterpriseName}, '%')


    AND MEASURE_TYPE = #{measureType}


    AND RISK_TYPE = #{riskType}


    AND PRIORITY_LEVEL = #{priorityLevel}


    AND IMPLEMENTATION_STATUS = #{implementationStatus}


    AND RESPONSIBLE_PERSON LIKE CONCAT('%', #{responsiblePerson}, '%')


    AND PLANNED_START_DATE >= #{startDate}


    AND PLANNED_END_DATE <= #{endDate}


    AND IMPLEMENTATION_PROGRESS >= #{minProgress}


    AND IMPLEMENTATION_PROGRESS <= #{maxProgress}

mapper.select:
SELECT IMPLEMENTATION_STATUS as status, COUNT(*) as count, ROUND(AVG(IMPLEMENTATION_PROGRESS), 2) as avgProgress, ROUND(COUNT(*) * 100.0 / (SELECT COUNT(*) FROM TBL_RISK_CONTROL_MEASURE WHERE DELETED = 0), 2) as percentage FROM TBL_RISK_CONTROL_MEASURE WHERE DELETED = 0
AND ENTERPRISE_ID = #{enterpriseId}
GROUP BY IMPLEMENTATION_STATUS ORDER BY CASE IMPLEMENTATION_STATUS WHEN 'PLANNED' THEN 1 WHEN 'IN_PROGRESS' THEN 2 WHEN 'COMPLETED' THEN 3 WHEN 'SUSPENDED' THEN 4 ELSE 5 END

SELECT CASE WHEN EFFECTIVENESS_SCORE >= 90 THEN 'EXCELLENT' WHEN EFFECTIVENESS_SCORE >= 80 THEN 'GOOD' WHEN EFFECTIVENESS_SCORE >= 70 THEN 'AVERAGE' WHEN EFFECTIVENESS_SCORE >= 60 THEN 'POOR' ELSE 'VERY_POOR' END as effectivenessLevel, COUNT(*) as count, ROUND(AVG(EFFECTIVENESS_SCORE), 2) as avgScore FROM TBL_RISK_CONTROL_MEASURE WHERE DELETED = 0 AND EFFECTIVENESS_SCORE IS NOT NULL
AND ENTERPRISE_ID = #{enterpriseId}
GROUP BY CASE WHEN EFFECTIVENESS_SCORE >= 90 THEN 'EXCELLENT' WHEN EFFECTIVENESS_SCORE >= 80 THEN 'GOOD' WHEN EFFECTIVENESS_SCORE >= 70 THEN 'AVERAGE' WHEN EFFECTIVENESS_SCORE >= 60 THEN 'POOR' ELSE 'VERY_POOR' END ORDER BY avgScore DESC
